use serde_json::{Value, Error as JsonError};
use std::str::FromStr;

fn rot13(c: char) -> char {
    if c.is_ascii_alphabetic() {
        let base = if c.is_ascii_lowercase() { 'a' } else { 'A' } as u8;
        let offset = c as u8 - base;
        let new_offset = (offset + 13) % 26;
        (base + new_offset) as char
    } else {
        c
    }
}

fn solve(input: Value) -> Result<Value, JsonError> {
    match input {
        Value::String(s) => {
            let rotated: String = s.chars().map(rot13).collect();
            Ok(Value::String(rotated))
        }
        Value::Array(arr) => {
            let rotated: Vec<Value> = arr.into_iter().map(solve).collect::<Result<Vec<Value>, JsonError>>()?;
            Ok(Value::Array(rotated))
        }
        Value::Object(obj) => {
            let rotated: serde_json::Map<String, Value> = obj.into_iter()
                .map(|(k, v)| (k, solve(v)))
                .collect::<Result<serde_json::Map<String, Value>, JsonError>>()?;
            Ok(Value::Object(rotated))
        }
        _ => Ok(input),
    }
}
